/**
 * The container image: `app/generated/Dockerfile`.
 *
 * This is the only artifact whose presence depends on *where* the app runs rather than on
 * what it does, so the tests here are about two things a reader cannot check by eye:
 *
 *   1. A spec that runs nothing as an image plans no image at all. An image nothing deploys
 *      would be regenerated byte-identically forever, which is how a dead file becomes
 *      permanent.
 *   2. The image runs the application that was generated, not a copy of it. The server
 *      entrypoint names `app.main:app`, which belongs to the application and is never
 *      emitted here -- a Dockerfile that invented an entrypoint would produce an image that
 *      builds and then answers nothing. A `batch` deployment is the same image entered
 *      through `app.generated.batch`, which the generator does emit.
 *
 * Nothing asserts the bytes: a Dockerfile is prose plus a small set of directives, and a
 * byte pin would fail on a comment edit while a missing `USER` slipped through. Each test
 * therefore names one property the image has to keep.
 */

import { describe, expect, it } from 'vitest';

import { DOCKERFILE_PATH, emitDockerfile, hasImageDeployment } from '../src/emit/dockerfile.js';
import { buildForSpecText, examplePlan, exampleSpecText, planFilesByOwner } from './helpers.js';

/** The example, with its one deployment pointed somewhere other than a container. */
function specWithTarget(target: string): string {
  return exampleSpecText()
    .replace('target: container', `target: ${target}`)
    .replace('streaming: true', 'streaming: false');
}

/** A manual pipeline appended to the example's `pipelines` block. */
const MANUAL_PIPELINE = [
  '  nightly_brief:',
  '    description: Summarise the day for the on-call engineer.',
  '    trigger:',
  '      manual: true',
  '    steps:',
  '      - generate:',
  '          prompt: customer_note',
  '          input:',
  '            customer: "{{ event.subject }}"',
  '          as: brief',
  '      - emit:',
  '          event: Answer',
  '',
].join('\n');

/**
 * The example with a batch job over a manual pipeline. The example declares 0.2, and the
 * batch surface arrives in 0.5, so the version moves with the construct.
 */
function specWithBatchJob(): string {
  return exampleSpecText()
    .replace('specVersion: "0.2"', 'specVersion: "0.5"')
    .replace('\ndeployments:\n', `\n${MANUAL_PIPELINE}\ndeployments:\n`)
    .replace(
      '    target: container\n    streaming: true',
      '    target: batch\n    pipeline: nightly_brief',
    );
}

/** The example plus a batch job, so one image has to serve both entrypoints. */
function specWithBatchAndContainer(): string {
  return exampleSpecText()
    .replace('specVersion: "0.2"', 'specVersion: "0.5"')
    .replace('\ndeployments:\n', `\n${MANUAL_PIPELINE}\ndeployments:\n`)
    .replace(
      '    secrets: [OPENAI_API_KEY]',
      '    secrets: [OPENAI_API_KEY]\n  nightly:\n    target: batch\n' +
        '    pipeline: nightly_brief\n    secrets: []',
    );
}

/** The example plus a second, imageless deployment carrying a secret of its own. */
function specWithSidecar(): string {
  return `${exampleSpecText()}\n  worker:\n    target: serverless\n    secrets: [SIDECAR_ONLY]\n`;
}

function plannedPaths(specText: string): string[] {
  return buildForSpecText(specText, 'app.spec.yaml')
    .plan.files.filter((file) => file.owner === 'generated')
    .map((file) => file.path);
}

describe('a container deployment', () => {
  it('plans the image, and only as a generated file', () => {
    expect(hasImageDeployment(buildForSpecText(exampleSpecText()).ir)).toBe(true);

    const image = examplePlan().files.find((file) => file.path === DOCKERFILE_PATH);
    expect(image?.owner).toBe('generated');
    expect(planFilesByOwner('generated').map((file) => file.path)).toContain(DOCKERFILE_PATH);
  });

  it('runs the application the generator emitted, through exec', () => {
    const { content } = emitDockerfile(buildForSpecText(exampleSpecText()).ir);

    expect(content).toContain('uvicorn app.main:app --host 0.0.0.0 --port');
    // `exec` replaces the shell, so SIGTERM from the platform reaches uvicorn rather than
    // stopping at a shell that does not forward it.
    expect(content).toContain('exec uvicorn');
  });

  it('does not run as root', () => {
    const { content } = emitDockerfile(buildForSpecText(exampleSpecText()).ir);

    expect(content).toMatch(/^USER (?!root)\S+$/m);
    expect(content).not.toMatch(/^USER root$/m);
  });

  it('names a declared secret in prose only, and never makes one a build argument', () => {
    const { content } = emitDockerfile(buildForSpecText(exampleSpecText()).ir);

    const directives = content
      .split('\n')
      .filter((line) => line.trim() !== '' && !line.trimStart().startsWith('#'));

    // The header tells the operator which environment variables to supply; no instruction
    // does, because the process reads them when a model is called.
    expect(content.split('\n').some((line) => line.includes('OPENAI_API_KEY'))).toBe(true);
    expect(directives.some((line) => line.includes('OPENAI_API_KEY'))).toBe(false);
    expect(content).not.toMatch(/^ARG /m);
  });

  it('ignores the secrets of a deployment that runs no image', () => {
    const { content } = emitDockerfile(buildForSpecText(specWithSidecar(), 'app.spec.yaml').ir);

    expect(content).toContain('OPENAI_API_KEY');
    expect(content).not.toContain('SIDECAR_ONLY');
  });

  it('is byte-identical on a second plan', () => {
    const { ir } = buildForSpecText(exampleSpecText());
    expect(emitDockerfile(ir).content).toBe(emitDockerfile(ir).content);
  });

  it('is plain LF text with one trailing newline and no tabs', () => {
    const { content } = emitDockerfile(buildForSpecText(exampleSpecText()).ir);

    expect(content).not.toContain('\r');
    expect(content).not.toContain('\t');
    expect(content.endsWith('\n')).toBe(true);
    expect(content.endsWith('\n\n')).toBe(false);
  });
});

describe('a spec that deploys no image', () => {
  it.each(['serverless', 'edge'])('plans %s without an image', (target) => {
    const specText = specWithTarget(target);
    expect(hasImageDeployment(buildForSpecText(specText, 'app.spec.yaml').ir)).toBe(false);
    expect(plannedPaths(specText)).not.toContain(DOCKERFILE_PATH);
  });
});

describe('a batch deployment', () => {
  it('plans the image, because the job is the image', () => {
    const specText = specWithBatchJob();
    expect(hasImageDeployment(buildForSpecText(specText, 'app.spec.yaml').ir)).toBe(true);
    expect(plannedPaths(specText)).toContain(DOCKERFILE_PATH);
  });

  it('enters the job instead of serving, and starts no server', () => {
    const { content } = emitDockerfile(buildForSpecText(specWithBatchJob(), 'app.spec.yaml').ir);

    // Exec form so the job definition can append the pipeline name.
    expect(content).toContain('ENTRYPOINT ["python", "-m", "app.generated.batch"]');
    // A job that listened on a port would never be reaped, so nothing declares one.
    expect(content).not.toMatch(/^EXPOSE /m);
    expect(content).not.toMatch(/^CMD /m);
    expect(content).not.toContain('uvicorn');
  });

  it('keeps the secrets a batch deployment declares', () => {
    const { content } = emitDockerfile(buildForSpecText(specWithBatchJob(), 'app.spec.yaml').ir);

    expect(content).toContain('OPENAI_API_KEY');
    expect(content).toMatch(/^# The image for deployments\.api \(`target: batch`\)\.$/m);
  });

  it('serves when a container shares the image, and leaves the job to override it', () => {
    const { content } = emitDockerfile(
      buildForSpecText(specWithBatchAndContainer(), 'app.spec.yaml').ir,
    );

    // `docker run` over this image should answer requests; the batch deployment replaces
    // the command through its own entrypoint rather than the image choosing for it.
    expect(content).toContain('exec uvicorn app.main:app');
    expect(content).not.toMatch(/^ENTRYPOINT /m);
    expect(content).toContain('with its entrypoint replaced');
  });
});
